values ('00000000-0000-4000-8000-d0c000000008', 'Safe internal cooking temperatures', 'USDA FSIS — Safe Minimum Internal Temperature Chart (summarised)', 'https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart', null, null, 'en', 'food_safety', null, 'documented', 'Summary in our own words of public-domain U.S. government guidance.', '9a1c7c6a2f6906933fd9c2e014f0a4099113d23b871d038eb6260319d04534d6')
on conflict do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000008', 0, 'Safe minimum internal temperatures, as published by food-safety agencies (USDA FSIS). Always measure with a food thermometer in the thickest part, away from bone.

Poultry (chicken, turkey, duck — whole, pieces or minced): 74 °C / 165 °F.

Minced or ground meat (beef, pork, veal, lamb), burgers and sausages: 71 °C / 160 °F.

Whole cuts of beef, pork, veal and lamb (steaks, chops, roasts): 63 °C / 145 °F, then rest for at least 3 minutes. Steak served rare or medium-rare is below this recommendation; it is a personal choice and is not advised for pregnant women, young children, older adults or people with weakened immunity.

Fish and shellfish: 63 °C / 145 °F, or until the flesh is opaque and flakes easily.

Egg dishes: 71 °C / 160 °F. Leftovers and casseroles: reheat to 74 °C / 165 °F.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000008') on conflict (document_id, position) do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000008', 1, 'the flesh is opaque and flakes easily.

Egg dishes: 71 °C / 160 °F. Leftovers and casseroles: reheat to 74 °C / 165 °F.
Do not leave cooked food at room temperature for more than 2 hours (1 hour above 32 °C / 90 °F). Refrigerate promptly and keep raw meat separate from ready-to-eat food. Wash hands, boards and utensils after handling raw meat, poultry or fish.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000008') on conflict (document_id, position) do nothing;

insert into public.knowledge_documents (id, title, source, source_url, manufacturer, model_number, language, doc_type, published_at, verification_status, rights_note, content_hash)
values ('00000000-0000-4000-8000-d0c000000009', 'Air frying fundamentals', 'CookPilot cooking guides', null, null, null, 'en', 'guide', '2026-11-09', 'documented', 'Original CookPilot text. General technique guidance, not manufacturer instructions.', 'd0745f4209e226932b31ccfa82553f58360d45cb2e8980243b70ac739ed21feb')
on conflict do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000009', 0, 'Air fryers cook with fast-moving hot air, so results depend on air reaching the food.

Dry food thoroughly before cooking; surface moisture prevents browning. Use a small amount of oil (about a teaspoon to a tablespoon) for fresh vegetables and potatoes. Arrange food in a single, loose layer and cook in batches rather than overfilling the basket. Shake the basket or turn the food halfway through for even colour.

Adapting a conventional oven recipe: as a starting point, lower the oven temperature by about 20 °C (25 °F) and reduce the time by roughly 20 %, then check early. These are general rules of thumb, not manufacturer settings — always confirm doneness with a thermometer for meat, poultry and fish.

Never exceed the maximum temperature documented for your model, and only use programs your model actually has.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000009') on conflict (document_id, position) do nothing;

insert into public.knowledge_documents (id, title, source, source_url, manufacturer, model_number, language, doc_type, published_at, verification_status, rights_note, content_hash)
values ('00000000-0000-4000-8000-d0c000000010', 'Indoor grilling fundamentals', 'CookPilot cooking guides', null, null, null, 'en', 'guide', '2026-11-09', 'documented', 'Original CookPilot text. General technique guidance, not manufacturer instructions.', '9d15b394851d28f965cc77860da8d136665a56369c154c530a4e2f66f09906a7')
on conflict do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000010', 0, 'Lidded indoor grills sear food on a preheated grill plate while hot air circulates under the closed lid.

Always let the appliance finish preheating before adding food; a hot plate gives grill marks and prevents sticking. Pat food dry and oil the food rather than the plate. Use an oil with a high smoke point for high-heat grilling. Fatty cuts and sugary marinades produce more smoke — ventilate the kitchen and wipe off excess marinade.

Cook meat to internal temperature rather than by time: thickness and starting temperature change cooking times considerably. Rest steaks and chops for a few minutes before slicing.

Some grills are set by level (for example LOW, MED, HIGH, MAX) instead of by degrees. Use the level names shown on your model and do not assume a degree value unless your owner''s guide states it.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000010') on conflict (document_id, position) do nothing;

insert into public.knowledge_documents (id, title, source, source_url, manufacturer, model_number, language, doc_type, published_at, verification_status, rights_note, content_hash)
values ('00000000-0000-4000-8000-d0c000000011', 'Frozen dessert maker fundamentals', 'CookPilot cooking guides', null, null, null, 'en', 'guide', '2026-11-09', 'documented', 'Original CookPilot text. General technique guidance, not manufacturer instructions.', 'f4dd8b83ce3484d6304617c1544a3d10351471fbc6ee705a0d6d98e059bd5efa')
on conflict do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000011', 0, 'Pint-processing dessert makers work on a base that is already frozen solid, which is different from churn-style ice cream makers.

Fill the container only up to the max fill line. Freeze it upright on a level surface with the lid on; a base frozen at an angle must not be processed. Ninja says to freeze the base overnight, and 24 hours is the commonly reported practice for a fully frozen pint.

Choose the program that matches the base: richer dairy bases for the ice cream or gelato programs, fruit-based bases for the sorbet program. If the result is crumbly or powdery after the first pass, add a tablespoon of liquid (milk for dairy bases, juice or water for sorbets) and process once more.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000011') on conflict (document_id, position) do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000011', 1, 'the first pass, add a tablespoon of liquid (milk for dairy bases, juice or water for sorbets) and process once more.
Mix-ins such as chocolate chips or biscuit pieces are added after the base has been processed: make a hole in the centre, add the pieces and run the mix-in program. Containers of different sizes are not interchangeable between models.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000011') on conflict (document_id, position) do nothing;

