values ('00000000-0000-4000-8000-d0c000000014', 'Honey & thyme roasted carrots', 'CookPilot demonstration recipes', null, null, null, 'en', 'recipe', '2026-11-09', 'partial', 'Original CookPilot recipe. Demonstration content, not physically tested.', '9172f9596d968010ecde7731a20cf83f44a239be2f4543a4a5d98e2b1e015e03')
