insert into public.knowledge_documents (id, title, source, source_url, manufacturer, model_number, language, doc_type, published_at, verification_status, rights_note, content_hash)
values ('00000000-0000-4000-8000-d0c000000027', 'Températures à cœur de sécurité', 'USDA FSIS — Safe Minimum Internal Temperature Chart (summarised)', 'https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart', null, null, 'fr', 'food_safety', null, 'documented', 'Summary in our own words of public-domain U.S. government guidance.', '7817a5c4aa6f7ff31b802b36eef1fd7db3a7123dec6ab2075c34434d40c6029e')
on conflict do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000027', 0, 'Températures minimales à cœur publiées par les agences de sécurité alimentaire (USDA FSIS). Mesurez toujours avec un thermomètre de cuisine dans la partie la plus épaisse, sans toucher l''os.

Volaille (poulet, dinde, canard — entière, en morceaux ou hachée) : 74 °C / 165 °F.

Viande hachée (bœuf, porc, veau, agneau), burgers et saucisses : 71 °C / 160 °F.

Pièces entières de bœuf, porc, veau et agneau (steaks, côtes, rôtis) : 63 °C / 145 °F, puis au moins 3 minutes de repos. Un steak servi bleu ou saignant se situe en dessous de cette recommandation ; c''est un choix personnel, déconseillé aux femmes enceintes, aux jeunes enfants, aux personnes âgées ou immunodéprimées.

Poissons et fruits de mer : 63 °C / 145 °F, ou jusqu''à ce que la chair soit opaque et s''effeuille facilement.

Plats à base d''œufs : 71 °C / 160 °F. Restes et plats mijotés : réchauffer à 74 °C / 165 °F.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000027') on conflict (document_id, position) do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000027', 1, 's''effeuille facilement.

Plats à base d''œufs : 71 °C / 160 °F. Restes et plats mijotés : réchauffer à 74 °C / 165 °F.
Ne laissez pas d''aliments cuits à température ambiante plus de 2 heures (1 heure au-delà de 32 °C). Réfrigérez rapidement et séparez les viandes crues des aliments prêts à consommer. Lavez-vous les mains, ainsi que les planches et ustensiles, après avoir manipulé de la viande, de la volaille ou du poisson crus.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000027') on conflict (document_id, position) do nothing;

insert into public.knowledge_documents (id, title, source, source_url, manufacturer, model_number, language, doc_type, published_at, verification_status, rights_note, content_hash)
values ('00000000-0000-4000-8000-d0c000000028', 'Les bases de la cuisson à l''air fryer', 'CookPilot cooking guides', null, null, null, 'fr', 'guide', '2026-11-09', 'documented', 'Original CookPilot text. General technique guidance, not manufacturer instructions.', '1486af0b198f6e0fed01bf9bc0fc1d94674d868e9ef217e03095fdf797fb8337')
on conflict do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000028', 0, 'Un air fryer cuit grâce à un flux d''air chaud rapide : le résultat dépend de la circulation de l''air autour des aliments.

Séchez soigneusement les aliments avant cuisson ; l''humidité en surface empêche de dorer. Utilisez un peu d''huile (d''une cuillère à café à une cuillère à soupe) pour les légumes frais et les pommes de terre. Disposez les aliments en une seule couche aérée et procédez en plusieurs fournées plutôt que de surcharger le panier. Secouez le panier ou retournez les aliments à mi-cuisson pour une coloration uniforme.

Adapter une recette de four traditionnel : comme point de départ, baissez la température d''environ 20 °C et réduisez le temps d''environ 20 %, puis contrôlez tôt. Ce sont des repères généraux, pas des réglages constructeur — vérifiez toujours la cuisson des viandes, volailles et poissons au thermomètre.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000028') on conflict (document_id, position) do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000028', 1, 'pas des réglages constructeur — vérifiez toujours la cuisson des viandes, volailles et poissons au thermomètre.
Ne dépassez jamais la température maximale documentée pour votre modèle et n''utilisez que les programmes réellement présents sur celui-ci.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000028') on conflict (document_id, position) do nothing;

insert into public.knowledge_documents (id, title, source, source_url, manufacturer, model_number, language, doc_type, published_at, verification_status, rights_note, content_hash)
values ('00000000-0000-4000-8000-d0c000000029', 'Les bases du gril d''intérieur', 'CookPilot cooking guides', null, null, null, 'fr', 'guide', '2026-11-09', 'documented', 'Original CookPilot text. General technique guidance, not manufacturer instructions.', '43319d40d56c50f60d6b8500d4487013de168638d2ca54f3796f71296387d046')
on conflict do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000029', 0, 'Un gril d''intérieur à couvercle saisit les aliments sur une plaque préchauffée pendant que l''air chaud circule sous le couvercle fermé.

Attendez toujours la fin du préchauffage avant de déposer les aliments ; une plaque bien chaude marque la viande et évite qu''elle n''attache. Séchez les aliments et huilez-les plutôt que la plaque. Choisissez une huile à point de fumée élevé pour les cuissons vives. Les pièces grasses et les marinades sucrées dégagent davantage de fumée — aérez la cuisine et essuyez l''excédent de marinade.

Cuisez la viande à la température à cœur plutôt qu''à la minute : l''épaisseur et la température de départ modifient fortement les temps. Laissez reposer steaks et côtes quelques minutes avant de trancher.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000029') on conflict (document_id, position) do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000029', 1, 'de départ modifient fortement les temps. Laissez reposer steaks et côtes quelques minutes avant de trancher.
Certains grils se règlent par niveau (par exemple LOW, MED, HIGH, MAX) et non en degrés. Utilisez les noms de niveaux affichés sur votre modèle et ne supposez aucune valeur en degrés si votre notice ne l''indique pas.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000029') on conflict (document_id, position) do nothing;

insert into public.knowledge_documents (id, title, source, source_url, manufacturer, model_number, language, doc_type, published_at, verification_status, rights_note, content_hash)
values ('00000000-0000-4000-8000-d0c000000030', 'Les bases des turbines à pot congelé', 'CookPilot cooking guides', null, null, null, 'fr', 'guide', '2026-11-09', 'documented', 'Original CookPilot text. General technique guidance, not manufacturer instructions.', 'f1870a63b2e43478ce124ced053d92042eb64d8e852ebbb6e05185e7fdbe2bf8')
on conflict do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000030', 0, 'Les turbines à pot travaillent une base déjà congelée à cœur, contrairement aux sorbetières classiques.

Remplissez le pot sans dépasser le repère maximal. Congelez-le debout, à plat, couvercle fermé ; une base congelée de travers ne doit pas être turbinée. Ninja indique de congeler la base une nuit, et 24 heures est la pratique couramment rapportée pour un pot congelé à cœur.

Choisissez le programme adapté à la base : bases lactées riches pour les programmes glace ou gelato, bases aux fruits pour le programme sorbet. Si le résultat est friable ou poudreux après le premier passage, ajoutez une cuillère à soupe de liquide (lait pour les bases lactées, jus ou eau pour les sorbets) et turbinez une seconde fois.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000030') on conflict (document_id, position) do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000030', 1, 'cuillère à soupe de liquide (lait pour les bases lactées, jus ou eau pour les sorbets) et turbinez une seconde fois.
Les ajouts comme les pépites de chocolat ou les morceaux de biscuit s''incorporent une fois la base turbinée : creusez un puits au centre, ajoutez les morceaux et lancez le programme d''ajouts (mix-in). Les pots de tailles différentes ne sont pas interchangeables entre modèles.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000030') on conflict (document_id, position) do nothing;

insert into public.knowledge_documents (id, title, source, source_url, manufacturer, model_number, language, doc_type, published_at, verification_status, rights_note, content_hash)
values ('00000000-0000-4000-8000-d0c000000031', 'Hauts de cuisse de poulet citron et herbes', 'CookPilot demonstration recipes', null, null, null, 'fr', 'recipe', '2026-11-09', 'partial', 'Original CookPilot recipe. Demonstration content, not physically tested.', '486aec10de4347ac9d6663656a131ff8109d536a9d304c309c4266be01462a2a')
on conflict do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000031', 0, '[recipe:00000000-0000-4000-8000-0ec100000001] Hauts de cuisse de poulet citron et herbes. Des hauts de cuisse à la peau croustillante, frottés au citron, à l''ail et au thym. Un classique de semaine qui demande très peu d''attention. Recette de démonstration CookPilot (non testée physiquement). Appareil : air-fryer. Modèles compatibles sur le papier : AF101, AF300EU. Pour 2 personnes. Ingrédients : 4 Hauts de cuisse de poulet avec os et peau; 1 tbsp Huile d''olive; 1 Citron; 2 clove Gousses d''ail finement râpées; 2 tsp Feuilles de thym frais; 1 tsp Sel fin; Poivre noir 1. Séchez soigneusement les hauts de cuisse avec du papier absorbant. Mélangez l''huile, le zeste de citron, l''ail, le thym, le sel et le poivre, puis frottez-en le poulet, y compris sous la peau. 2. Préchauffez l''air fryer en mode Air Fry à 200 °C pendant 3 minutes. [air-fry, 200 °C, 3 min] 3.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000031') on conflict (document_id, position) do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000031', 1, 'sous la peau. 2. Préchauffez l''air fryer en mode Air Fry à 200 °C pendant 3 minutes. [air-fry, 200 °C, 3 min] 3.
Déposez les hauts de cuisse côté peau vers le bas, en une seule couche. Faites cuire 12 minutes. [air-fry, 200 °C, 12 min] 4. Retournez les hauts de cuisse, peau vers le haut, et poursuivez la cuisson 10 à 12 minutes, jusqu''à ce que la peau soit bien dorée et que la partie la plus épaisse atteigne 74 °C. [air-fry, 200 °C, 11 min] 5. Laissez reposer 5 minutes, arrosez de jus de citron et servez. [5 min] Sécurité : La volaille est sûre lorsque la partie la plus épaisse atteint 74 °C (165 °F). Fiez-vous à un thermomètre plutôt qu''à la couleur. Lavez-vous les mains, ainsi que les planches et ustensiles, après avoir manipulé du poulet cru.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000031') on conflict (document_id, position) do nothing;

