on conflict do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000032', 0, '[recipe:00000000-0000-4000-8000-0ec100000002] Potatoes croustillantes au paprika. Des quartiers de pommes de terre trempés, séchés et légèrement huilés : croustillants sur les bords, moelleux à cœur. Recette de démonstration CookPilot (non testée physiquement). Appareil : air-fryer. Modèles compatibles sur le papier : AF101, AF300EU. Pour 2 personnes. Ingrédients : 500 g Pommes de terre à chair farineuse; 1 tbsp Huile neutre; 1 tsp Paprika fumé; 0.5 tsp Ail en poudre; 0.5 tsp Sel fin 1. Coupez les pommes de terre en quartiers réguliers d''environ 2 cm d''épaisseur. Faites-les tremper 10 minutes dans l''eau froide, puis égouttez et séchez-les soigneusement dans un torchon propre. [10 min] 2. Mélangez les quartiers avec l''huile, le paprika, l''ail en poudre et le sel jusqu''à ce qu''ils soient bien enrobés. 3. Faites cuire en mode Air Fry à 200 °C pendant 10 minutes, en une seule couche aérée.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000032') on conflict (document_id, position) do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000032', 1, 'ce qu''ils soient bien enrobés. 3. Faites cuire en mode Air Fry à 200 °C pendant 10 minutes, en une seule couche aérée.
[air-fry, 200 °C, 10 min] 4. Secouez bien le panier, puis poursuivez la cuisson 10 à 12 minutes jusqu''à ce qu''elles soient dorées et croustillantes. [air-fry, 200 °C, 11 min] Sécurité : Le panier et le tiroir sont très chauds après la cuisson — utilisez la poignée et posez le tiroir sur une surface résistante à la chaleur.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000032') on conflict (document_id, position) do nothing;

