insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000033', 0, '[recipe:00000000-0000-4000-8000-0ec100000003] Carottes rôties au miel et au thym. Des carottes tendres et légèrement caramélisées, relevées de miel et de thym. Assez simples pour un mardi soir, assez jolies pour recevoir. Recette de démonstration CookPilot (non testée physiquement). Appareil : air-fryer. Modèles compatibles sur le papier : AF101, AF300EU. Pour 2 personnes. Ingrédients : 400 g Carottes; 1 tbsp Huile d''olive; 2 tsp Miel; 3 sprig Brins de thym frais; 0.5 tsp Sel fin 1. Mélangez les carottes avec l''huile d''olive et le sel. 2. Faites cuire en mode Roast à 190 °C pendant 12 minutes, en secouant le panier à mi-cuisson. [roast, 190 °C, 12 min] 3. Arrosez de miel, ajoutez le thym et mélangez. Poursuivez la cuisson 3 à 4 minutes, jusqu''à ce que les carottes soient brillantes et tendres sous la pointe d''un couteau. [roast, 190 °C, 3 min 30 s]' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000033') on conflict (document_id, position) do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000033', 1, 'jusqu''à ce que les carottes soient brillantes et tendres sous la pointe d''un couteau. [roast, 190 °C, 3 min 30 s]
Sécurité : Le miel ne convient pas aux enfants de moins d''un an.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000033') on conflict (document_id, position) do nothing;

