insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000034', 0, '[recipe:00000000-0000-4000-8000-0ec100000004] Pavés de saumon au citron et à l''aneth. Un saumon cuit juste à point, doré en surface, avec une sauce minute au citron et à l''aneth. À table en un quart d''heure. Recette de démonstration CookPilot (non testée physiquement). Appareil : air-fryer. Modèles compatibles sur le papier : AF101, AF300EU. Pour 2 personnes. Ingrédients : 2 Pavés de saumon avec la peau; 2 tsp Huile d''olive; 0.5 tsp Sel fin; 1 tbsp Jus de citron; 1 tbsp Aneth frais ciselé 1. Séchez le saumon, frottez-le avec la moitié de l''huile et salez. 2. Faites cuire côté peau vers le bas en mode Air Fry à 200 °C pendant 8 à 10 minutes selon l''épaisseur, jusqu''à ce que la chair s''effeuille facilement et que le cœur atteigne 63 °C. [air-fry, 200 °C, 9 min] 3. Mélangez le jus de citron, l''aneth et le reste d''huile. Nappez le saumon et servez aussitôt.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000034') on conflict (document_id, position) do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000034', 1, '200 °C, 9 min] 3. Mélangez le jus de citron, l''aneth et le reste d''huile. Nappez le saumon et servez aussitôt.
Sécurité : Les agences de sécurité alimentaire recommandent de cuire le poisson à une température à cœur de 63 °C (145 °F). Contient du poisson.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000034') on conflict (document_id, position) do nothing;

insert into public.knowledge_documents (id, title, source, source_url, manufacturer, model_number, language, doc_type, published_at, verification_status, rights_note, content_hash)
values ('00000000-0000-4000-8000-d0c000000035', 'Entrecôte grillée au beurre d''ail', 'CookPilot demonstration recipes', null, null, null, 'fr', 'recipe', '2026-11-09', 'partial', 'Original CookPilot recipe. Demonstration content, not physically tested.', 'fc5ceedaf28556a1ab60b43dd6be4679b2f60d5084b373880349fa659ca237e2')
on conflict do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000035', 0, '[recipe:00000000-0000-4000-8000-0ec100000005] Entrecôte grillée au beurre d''ail. Une entrecôte épaisse saisie sur une plaque bien chaude et terminée au beurre d''ail et persil. Cuisez à la température, pas à la minute. Recette de démonstration CookPilot (non testée physiquement). Appareil : indoor-grill. Modèles compatibles sur le papier : AG301. Pour 2 personnes. Ingrédients : 500 g Entrecôte de 3 cm d''épaisseur; 2 tsp Huile neutre à point de fumée élevé; 1 tsp Fleur de sel; 30 g Beurre mou; 1 clove Gousse d''ail finement râpée; 1 tbsp Persil plat ciselé 1. Écrasez le beurre avec l''ail et le persil, puis réservez. Séchez l''entrecôte, huilez-la et salez généreusement. 2. Installez la plaque de gril, fermez le couvercle et préchauffez en mode Grill, niveau HIGH, jusqu''à ce que l''appareil signale qu''il est prêt. [grill, HIGH] 3.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000035') on conflict (document_id, position) do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000035', 1, 'Posez l''entrecôte sur la plaque, fermez le couvercle et faites griller 4 minutes. [grill, HIGH, 4 min] 4. Retournez et faites griller encore 3 à 5 minutes. Contrôlez tôt : retirez à 52–54 °C pour une cuisson saignante à rosée (la température monte encore de quelques degrés au repos), ou à 63 °C pour la cuisson officiellement recommandée. [grill, HIGH, 4 min] 5. Déposez le beurre d''ail sur la viande et laissez reposer 5 minutes avant de trancher perpendiculairement aux fibres. [5 min] Sécurité : Les agences de sécurité alimentaire recommandent 63 °C (145 °F) suivis de 3 minutes de repos pour les pièces de bœuf entières. Une cuisson saignante se situe en dessous : c''est un choix personnel, déconseillé aux femmes enceintes, aux personnes âgées ou immunodéprimées. La cuisson de pièces grasses dégage de la fumée — éloignez l''appareil des placards et aérez la cuisine.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000035') on conflict (document_id, position) do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000035', 2, 'La cuisson de pièces grasses dégage de la fumée — éloignez l''appareil des placards et aérez la cuisine.
Contient du lait (beurre).' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000035') on conflict (document_id, position) do nothing;

insert into public.knowledge_documents (id, title, source, source_url, manufacturer, model_number, language, doc_type, published_at, verification_status, rights_note, content_hash)
values ('00000000-0000-4000-8000-d0c000000036', 'Brochettes de légumes grillés à l''huile d''herbes', 'CookPilot demonstration recipes', null, null, null, 'fr', 'recipe', '2026-11-09', 'partial', 'Original CookPilot recipe. Demonstration content, not physically tested.', '2fa1eb104815fa6d696606d09185d5e14b9e3de7775422f9338e89e85289ec3b')
on conflict do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000036', 0, '[recipe:00000000-0000-4000-8000-0ec100000006] Brochettes de légumes grillés à l''huile d''herbes. Courgette, poivron, oignon rouge et champignons, légèrement grillés et badigeonnés d''une huile d''herbes citronnée. Recette de démonstration CookPilot (non testée physiquement). Appareil : indoor-grill. Modèles compatibles sur le papier : AG301. Pour 2 personnes. Ingrédients : 1 Courgette en demi-rondelles épaisses; 1 Poivron rouge en morceaux de 3 cm; 1 Oignon rouge en quartiers; 150 g Champignons de Paris bruns; 2 tbsp Huile d''olive; 1 tbsp Jus de citron; 2 tbsp Persil et origan ciselés; 0.5 tsp Sel fin 1. Si vous utilisez des piques en bois, faites-les tremper 15 minutes dans l''eau. Enfilez les légumes en alternant les couleurs, puis badigeonnez-les de la moitié de l''huile d''olive. Salez. 2. Installez la plaque de gril, fermez le couvercle et préchauffez en mode Grill, niveau MED.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000036') on conflict (document_id, position) do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000036', 1, 'l''huile d''olive. Salez. 2. Installez la plaque de gril, fermez le couvercle et préchauffez en mode Grill, niveau MED.
[grill, MED] 3. Faites griller les brochettes 8 à 10 minutes en les retournant à mi-cuisson, jusqu''à ce que les légumes soient tendres et marqués. [grill, MED, 9 min] 4. Mélangez le reste d''huile avec le jus de citron et les herbes, puis badigeonnez-en les brochettes chaudes. Sécurité : Les pointes des piques et la plaque restent brûlantes — utilisez une pince pour retourner et servir.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000036') on conflict (document_id, position) do nothing;

insert into public.knowledge_documents (id, title, source, source_url, manufacturer, model_number, language, doc_type, published_at, verification_status, rights_note, content_hash)
values ('00000000-0000-4000-8000-d0c000000037', 'Glace à la vanille en gousse', 'CookPilot demonstration recipes', null, null, null, 'fr', 'recipe', '2026-11-09', 'partial', 'Original CookPilot recipe. Demonstration content, not physically tested.', '7d663122f3bd25a06bd93afd04c1af4857b79b75442c79a4e317cfc260f17745')
on conflict do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000037', 0, '[recipe:00000000-0000-4000-8000-0ec100000007] Glace à la vanille en gousse. Une base sans cuisson au fromage frais qui donne une glace vanille lisse et onctueuse. Préparez la base aujourd''hui, turbinez demain. Recette de démonstration CookPilot (non testée physiquement). Appareil : frozen-dessert-maker. Modèles compatibles sur le papier : NC301, NC300EU. Pour 4 personnes. Ingrédients : 15 g Fromage frais entier, ramolli; 65 g Sucre en poudre; 1 Gousse de vanille, graines grattées; 180 ml Crème liquide entière; 240 ml Lait entier 1. Fouettez le fromage frais, le sucre et les graines de vanille jusqu''à obtenir une pâte lisse. Incorporez peu à peu la crème et le lait jusqu''à dissolution du sucre. 2. Versez dans le pot sans dépasser le repère de remplissage maximal. Fermez le couvercle et congelez à plat pendant 24 heures. [24 h] 3.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000037') on conflict (document_id, position) do nothing;
insert into public.knowledge_chunks (document_id, position, content) select '00000000-0000-4000-8000-d0c000000037', 1, 'pot sans dépasser le repère de remplissage maximal. Fermez le couvercle et congelez à plat pendant 24 heures. [24 h] 3.
Retirez le couvercle, verrouillez le pot dans le bol extérieur puis sur la machine, et lancez le programme Ice Cream. [ice-cream] 4. Si la texture est friable, ajoutez une cuillère à soupe de lait et turbinez une seconde fois. Servez aussitôt. Sécurité : Contient du lait. Ne turbinez jamais un pot congelé de travers ou rempli au-delà du repère maximal.' where exists (select 1 from public.knowledge_documents where id = '00000000-0000-4000-8000-d0c000000037') on conflict (document_id, position) do nothing;

